export const commonMessages:Record<string,Record<Language,string>>={};
for(const row of rows){const [source,...translated]=row;commonMessages[source]=Object.fromEntries(languages.map((language,index)=>[language,index===0?source:translated[index-1]])) as Record<Language,string>}
commonMessages['Organization haijapatikana.'].en='Organization was not found.';
// Reuse the canonical navigation vocabulary rather than maintaining competing translations.
for(const key of Object.keys(dictionaries.en) as (keyof typeof dictionaries.en)[]){const source=dictionaries.en[key];commonMessages[source]=Object.fromEntries(languages.map(language=>[language,dictionaries[language][key]])) as Record<Language,string>}
for(const source of ['Qty','Store','Status','Total','Amount','Date','Name','Phone','Email','Category','Balance','Note']){const entry=commonMessages[source];commonMessages[source+':']=Object.fromEntries(languages.map(language=>[language,entry[language]+':'])) as Record<Language,string>}
for(const row of completionRows){const [source,...translated]=row;commonMessages[source]=Object.fromEntries(languages.map((language,index)=>[language,index===0?source:translated[index-1]])) as Record<Language,string>}
export function translateCommon(language:Language,source:string,params?:Readonly<Record<string,string|number>>){
 const message=commonMessages[source]?.[language]||commonMessages[source]?.en||source;
 return message.replace(/\{([A-Za-z][A-Za-z0-9_]*)\}/g,(token,key)=>params&&Object.prototype.hasOwnProperty.call(params,key)?String(params[key]):token);
}

